CREATE VIEW std_access_status AS WITH ownership_raw AS ((SELECT 'PS4' AS platform_name, main."trim"(Title) AS game_title, main."trim"(CAST("Owned?" AS VARCHAR)) AS owned_raw FROM stg_ps4_inventory) UNION ALL ((SELECT 'PS5' AS platform_name, main."trim"(Title) AS game_title, main."trim"(CAST("Owned?" AS VARCHAR)) AS owned_raw FROM stg_ps5_inventory) UNION ALL (SELECT 'Wii U' AS platform_name, main."trim"(Title) AS game_title, main."trim"(CAST("Owned" AS VARCHAR)) AS owned_raw FROM stg_wiiu_inventory))), ownership_standardized AS (SELECT o.platform_name, o.game_title, m.canonical_value AS owned_flag FROM ownership_raw AS o LEFT JOIN map_owned_flag AS m ON ((o.owned_raw = m.raw_value)))SELECT s.platform_name, s.game_title, o.owned_flag, CASE  WHEN ((s.play_status_raw = 'Removed')) THEN ('Removed') WHEN ((o.owned_flag = CAST('t' AS BOOLEAN))) THEN ('Available') ELSE 'Unknown' END AS access_status FROM std_all_inventory AS s LEFT JOIN ownership_standardized AS o ON (((s.platform_name = o.platform_name) AND (s.game_title = o.game_title)));
